L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "\227\129\175\227\129\152\227\130\129\227\129\139\227\130\137\227\129\130\227\129\170\227\129\159\227\129\175\226\128\166\226\128\166\231\167\129\227\129\174\228\191\161\229\191\181\227\129\168\227\129\174\229\133\177\229\173\152\227\129\175\227\129\167\227\129\141\227\129\170\227\129\139\227\129\163\227\129\159\227\129\174\227\129\167\227\129\153\227\128\130"
