L16_1.m_Talk_THA = L17_1
L17_1 = "Ngay t\225\187\171 \196\145\225\186\167u t\195\180i \196\145\195\163 bi\225\186\191t r\225\186\177ng... c\195\180 kh\195\180ng th\225\187\131 c\195\185ng t\225\187\147n t\225\186\161i v\225\187\155i \196\145\225\187\169c tin c\225\187\167a t\195\180i."
L16_1.m_Talk_VTN = L17_1
L17_1 = "\228\187\142\230\156\128\229\188\128\229\167\139\226\128\166\226\128\166\228\189\160\229\176\177\230\151\160\230\179\149\229\146\140\230\136\145\231\154\132\228\191\161\229\191\181\229\133\177\229\173\152\227\128\130"
